import zlib
def lzip_dict_code(n):
    # returns byte b such that decoded size == n if representable
    for base in range(12,30):
        for sub in range(8):
            size = (1<<base) - ((1<<base)//16)*sub
            if size==n: return (sub<<5)|base
    return None

def lzip_member(data, version=1, dictcode=None, lc=3, lp=0, pb=2,
                crc=None, usize=None, msize=None, body=None):
    if body is None:
        body = encode_lzma1(data, lc, lp, pb, True)
    if dictcode is None: dictcode = 23  # 2^23 = 8 MiB
    hdr = b'LZIP' + bytes([version, dictcode])
    if crc is None: crc = zlib.crc32(data) & 0xFFFFFFFF
    if usize is None: usize = len(data)
    m = hdr + body
    if msize is None: msize = len(m) + (20 if version>=1 else 12)
    if version >= 1:
        foot = struct.pack('<IQQ', crc, usize, msize)
    else:
        foot = struct.pack('<IQ', crc, usize)
    return m + foot
